/**
 * @event
 * @name scwin.btn_findCompanyName_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_findCompanyName_onclick = function(e){
    try {
        const ev = e;
