/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param no
 * @returns
 * @hidden N
*/
scwin.fnSearch = function (no) {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const searchForm = $('#searchForm');
    if (($c.util.getComponent("slc_showMonth").getValue() || '') < 10) {
        $c.util.getComponent("ipt_selMonth").setValue("0" + document.searchForm.find('select[name=slc_showMonth]').val());
    } else {
        $c.util.getComponent("ipt_selMonth").setValue(document.searchForm.find('select[name=slc_showMonth]').val());
    }
    let method = "searchTotalCalendar";
    let forward = "searchtotalcalendar";
    if (no === "11") {
        $(document).find('div[id=search]').css("display", "block");
    } else {
        $(document).find('div[id=search]').css("display", "none");
    }
    switch (no) {
        case "01":
        method = "searchTotalCalendar";
        forward = "searchtotalcalendar";
        break;
        case "02":
        method = "searchPaidinCapitalIncrease";
        forward = "searchpaidincapitalincrease";
        break;
        case "03":
        method = "searchFreeIssueNewShares";
        forward = "searchfreeissuenewshares";
        break;
        case "04":
        method = "searchFaceValueChange";
        forward = "searchfacevaluechange";
        break;
        case "05":
        method = "searchStockDividend";
        forward = "searchstockdividend";
        break;
        case "06":
        method = "searchReductionCapital";
        forward = "searchreductioncapital";
        break;
        case "07":
        method = "searchDivisionAffiliation";
        forward = "searchdivisionaffiliation";
        break;
        case "08":
        method = "searchNameChange";
        forward = "searchnamechange";
        break;
        case "09":
        method = "searchBalancingAccountsResultSch";
        forward = "searchbalancingaccountsresultsch";
        break;
        case "10":
        method = "searchGeneralMeetingStockholders";
        forward = "searchgeneralmeetingstockholders";
        break;
        case "11":
        method = "searchAuditReportReleaseState";
        forward = "searchauditreportreleasestate";
        break;
        case "12":
        method = "searchInsincerityDistribute";
        forward = "searchinsinceritydistribute";
        break;
        case "13":
        method = "searchTraidingCalendar";
        forward = "searchtraidingcalendar";
        break;
    }
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("searchMenu", no);
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", method);
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("forward", forward);
    document.searchForm.ajaxSubmit({ ajaxUrl: '/common/stockschedule.do', ajaxCallBack: scwin.fnSearchCallBack });
    /* sdd-asis-lifecycle:end */
};


